function defaultPermissionsForRole(role) {
  if (role === 'admin') {
    return {
      canViewInventory: true,
      canManageItems: true,
      canRecordIn: true,
      canRecordOut: true,
      canApprove: true,
      canManageUsers: true,
      canSyncSheets: true,
      canDeleteData: true,
    };
  }
  if (role === 'manager') {
    return {
      canViewInventory: true,
      canManageItems: true,
      canRecordIn: true,
      canRecordOut: true,
      canApprove: true,
      canManageUsers: false,
      canSyncSheets: true,
      canDeleteData: false,
    };
  }
  return {
    canViewInventory: true,
    canManageItems: false,
    canRecordIn: true,
    canRecordOut: true,
    canApprove: false,
    canManageUsers: false,
    canSyncSheets: false,
    canDeleteData: false,
  };
}

function mergePermissions(role, incoming) {
  const base = defaultPermissionsForRole(role);
  if (!incoming || typeof incoming !== 'object') return base;
  return {
    canViewInventory: Boolean(incoming.canViewInventory ?? base.canViewInventory),
    canManageItems: Boolean(incoming.canManageItems ?? base.canManageItems),
    canRecordIn: Boolean(incoming.canRecordIn ?? base.canRecordIn),
    canRecordOut: Boolean(incoming.canRecordOut ?? base.canRecordOut),
    canApprove: Boolean(incoming.canApprove ?? base.canApprove),
    canManageUsers: Boolean(incoming.canManageUsers ?? base.canManageUsers),
    canSyncSheets: Boolean(incoming.canSyncSheets ?? base.canSyncSheets),
    canDeleteData: Boolean(incoming.canDeleteData ?? base.canDeleteData),
  };
}

function toHex(bytes) {
  return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
}

function fromHex(hex) {
  const clean = hex.trim();
  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function base64UrlEncode(bytes) {
  let binary = '';
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function base64Decode(b64) {
  const binary = atob(b64);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    out[i] = binary.charCodeAt(i);
  }
  return out;
}

function base64UrlDecode(str) {
  const padded = str.replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((str.length + 3) % 4);
  const binary = atob(padded);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    out[i] = binary.charCodeAt(i);
  }
  return out;
}

function constantTimeEqual(a, b) {
  if (a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) {
    diff |= a[i] ^ b[i];
  }
  return diff === 0;
}

async function hashPassword(password) {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(password),
    'PBKDF2',
    false,
    ['deriveBits'],
  );
  const derived = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' },
    keyMaterial,
    256,
  );
  return `pbkdf2:${toHex(salt)}:${toHex(new Uint8Array(derived))}`;
}

async function verifyPassword(password, storedHash) {
  const parts = String(storedHash || '').split(':');
  if (parts.length !== 3 || parts[0] !== 'pbkdf2') return false;
  const salt = fromHex(parts[1]);
  const expected = fromHex(parts[2]);
  const keyMaterial = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(password),
    'PBKDF2',
    false,
    ['deriveBits'],
  );
  const derived = await crypto.subtle.deriveBits(
    { name: 'PBKDF2', salt, iterations: 100000, hash: 'SHA-256' },
    keyMaterial,
    256,
  );
  return constantTimeEqual(new Uint8Array(derived), expected);
}

async function signHmac(data, secret) {
  const key = await crypto.subtle.importKey(
    'raw',
    new TextEncoder().encode(secret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  );
  const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(data));
  return base64UrlEncode(new Uint8Array(sig));
}

async function createToken(user, secret) {
  const payload = { sub: user.id, exp: Date.now() + TOKEN_TTL_MS };
  const encoded = base64UrlEncode(new TextEncoder().encode(JSON.stringify(payload)));
  const sig = await signHmac(encoded, secret);
  return `${encoded}.${sig}`;
}

async function verifyToken(token, secret) {
  if (!token || !token.includes('.')) return null;
  const [encoded, sig] = token.split('.');
  if (!encoded || !sig) return null;
  const expectedSig = await signHmac(encoded, secret);
  const a = new TextEncoder().encode(sig);
  const b = new TextEncoder().encode(expectedSig);
  if (!constantTimeEqual(a, b)) return null;
  try {
    const raw = new TextDecoder().decode(base64UrlDecode(encoded));
    const payload = JSON.parse(raw);
    if (!payload?.sub || !payload?.exp || Date.now() > payload.exp) return null;
    return String(payload.sub);
  } catch {
    return null;
  }
}

async function ensureColumns(db, tableName, columns) {
  const info = await db.prepare(`PRAGMA table_info(${tableName})`).all();
  const existing = new Set((info.results || []).map((r) => String(r.name)));
  for (const [colName, colDef] of columns) {
    if (!existing.has(colName)) {
      await db.prepare(`ALTER TABLE ${tableName} ADD COLUMN ${colName} ${colDef}`).run();
    }
  }
}

