async function getTokenSecret(env) {
  if (env.TOKEN_SECRET && String(env.TOKEN_SECRET).trim()) {
    return String(env.TOKEN_SECRET).trim();
  }
  const row = await env.DB.prepare('SELECT value FROM app_secrets WHERE key = ?')
    .bind('token_secret')
    .first();
  if (row?.value) return String(row.value);
  const generated = toHex(crypto.getRandomValues(new Uint8Array(32)));
  await env.DB.prepare('INSERT OR IGNORE INTO app_secrets (key, value) VALUES (?, ?)')
    .bind('token_secret', generated)
    .run();
  const saved = await env.DB.prepare('SELECT value FROM app_secrets WHERE key = ?')
    .bind('token_secret')
    .first();
  return String(saved?.value || generated);
}

