async function syncToAppsScriptWebhook(webhookUrl, tabs, options = {}) {
  if (!isValidAppsScriptUrl(webhookUrl)) {
    throw new Error('آدرس وب‌هوک باید یک لینک معتبر https://script.google.com/macros/... باشد.');
  }
  const res = await fetch(webhookUrl.trim(), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      tabs,
      spreadsheetId: options.spreadsheetId || '',
      spreadsheetTitle: options.spreadsheetTitle || 'سامانه انبارداری - گزارش آنلاین',
    }),
    redirect: 'follow',
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`خطای وب‌هوک گوگل شیت (${res.status}): ${errText.slice(0, 200)}`);
  }
  const text = await res.text();
  try {
    const parsed = JSON.parse(text);
    return {
      spreadsheetId: typeof parsed.spreadsheetId === 'string' ? parsed.spreadsheetId : undefined,
      spreadsheetUrl: typeof parsed.spreadsheetUrl === 'string' ? parsed.spreadsheetUrl : undefined,
    };
  } catch {
    return {};
  }
}

async function createWarehouseSpreadsheet(googleAccessToken, title) {
  const cleanTitle = String(title || '').trim() || 'سامانه انبارداری - گزارش آنلاین';
  const res = await fetch('https://sheets.googleapis.com/v4/spreadsheets', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${googleAccessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      properties: { title: cleanTitle, locale: 'fa_IR' },
      sheets: REQUIRED_TABS.map((tabName) => ({
        properties: {
          title: tabName,
          rightToLeft: true,
          gridProperties: { frozenRowCount: 1 },
        },
      })),
    }),
  });
  if (!res.ok) {
    const errText = await res.text();
    throw new Error(`Google Sheets API create failed (${res.status}): ${errText}`);
  }
  const data = await res.json();
  return {
    spreadsheetId: data.spreadsheetId,
    spreadsheetUrl:
      data.spreadsheetUrl || `https://docs.google.com/spreadsheets/d/${data.spreadsheetId}/edit`,
    title: data.properties?.title || cleanTitle,
  };
}

async function syncToGoogleSheetsViaOAuth(googleAccessToken, spreadsheetId, tabs) {
  const metaRes = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${encodeURIComponent(spreadsheetId)}?fields=sheets.properties.title`,
    { headers: { Authorization: `Bearer ${googleAccessToken}` } },
  );
  if (!metaRes.ok) {
    const errText = await metaRes.text();
    throw new Error(`خطا در خواندن اطلاعات گوگل شیت (${metaRes.status}): ${errText}`);
  }
  const meta = await metaRes.json();
  const existingTitles = new Set(
    (meta.sheets || []).map((s) => s.properties?.title).filter(Boolean),
  );
  const missingTabs = tabs.filter((t) => !existingTitles.has(t.tabName));
  if (missingTabs.length > 0) {
    const addRes = await fetch(
      `https://sheets.googleapis.com/v4/spreadsheets/${encodeURIComponent(spreadsheetId)}:batchUpdate`,
      {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${googleAccessToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          requests: missingTabs.map((t) => ({
            addSheet: {
              properties: {
                title: t.tabName,
                rightToLeft: true,
                gridProperties: { frozenRowCount: 1 },
              },
            },
          })),
        }),
      },
    );
    if (!addRes.ok) {
      const errText = await addRes.text();
      throw new Error(`خطا در ایجاد برگه‌های گوگل شیت (${addRes.status}): ${errText}`);
    }
  }
  const clearRes = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${encodeURIComponent(spreadsheetId)}/values:batchClear`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${googleAccessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({ ranges: tabs.map((t) => `'${t.tabName}'!A:Z`) }),
    },
  );
  if (!clearRes.ok) {
    const errText = await clearRes.text();
    throw new Error(`خطا در پاکسازی محدوده شیت (${clearRes.status}): ${errText}`);
  }
  const updateRes = await fetch(
    `https://sheets.googleapis.com/v4/spreadsheets/${encodeURIComponent(spreadsheetId)}/values:batchUpdate`,
    {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${googleAccessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        valueInputOption: 'USER_ENTERED',
        data: tabs.map((t) => ({
          range: `'${t.tabName}'!A1`,
          majorDimension: 'ROWS',
          values: [t.headers, ...t.rows],
        })),
      }),
    },
  );
  if (!updateRes.ok) {
    const errText = await updateRes.text();
    throw new Error(`خطا در ثبت اطلاعات در گوگل شیت (${updateRes.status}): ${errText}`);
  }
}

async function listItems(db) {
  const res = await db.prepare('SELECT * FROM items ORDER BY created_at ASC').all();
  return (res.results || []).map(mapItemRow);
}

async function listMovements(db) {
  const res = await db.prepare('SELECT * FROM movements ORDER BY date DESC, created_at DESC').all();
  return (res.results || []).map(mapMovementRow);
}

async function listUsers(db) {
  const res = await db.prepare('SELECT * FROM users ORDER BY created_at ASC').all();
  return (res.results || []).map(mapUserRow);
}

async function getSheetConfig(db) {
  const row = await db.prepare('SELECT * FROM sheet_config WHERE id = 1').first();
  return mapSheetConfigRow(row);
}

async function markAllMovementsSync(db, status, message) {
  const now = new Date().toISOString();
  await db.batch([
    db
      .prepare('UPDATE movements SET sheet_sync_status = ?, sheet_sync_error = ?')
      .bind(status, status === 'error' ? message : null),
    db
      .prepare('UPDATE sheet_config SET last_synced_at = ?, last_sync_message = ? WHERE id = 1')
      .bind(now, message),
  ]);
}

async function tryBackgroundWebhookSync(env) {
  const cfg = await getSheetConfig(env.DB);
  if (!cfg.autoSyncOnChange || !cfg.webhookUrl || !isValidAppsScriptUrl(cfg.webhookUrl)) {
    return;
  }
  try {
    const [items, movements] = await Promise.all([listItems(env.DB), listMovements(env.DB)]);
    const tabs = buildGoogleSheetPayloads(items, movements);
    const result = await syncToAppsScriptWebhook(cfg.webhookUrl, tabs, {
      spreadsheetId: cfg.spreadsheetId,
      spreadsheetTitle: cfg.spreadsheetTitle,
    });
    if (!cfg.spreadsheetId && result.spreadsheetId) {
      const sheetUrl =
        result.spreadsheetUrl ||
        `https://docs.google.com/spreadsheets/d/${result.spreadsheetId}/edit`;
      await env.DB.prepare(
        'UPDATE sheet_config SET spreadsheet_id = ?, spreadsheet_url = ? WHERE id = 1',
      )
        .bind(result.spreadsheetId, sheetUrl)
        .run();
    }
    await markAllMovementsSync(env.DB, 'synced', 'همگام‌سازی خودکار ۴ برگه با گوگل شیت انجام شد');
  } catch (err) {
    const msg = err instanceof Error ? err.message : 'خطای همگام‌سازی خودکار';
    await markAllMovementsSync(env.DB, 'error', msg);
  }
}

function scheduleSync(ctx, env) {
  const task = tryBackgroundWebhookSync(env);
  if (ctx && typeof ctx.waitUntil === 'function') {
    ctx.waitUntil(task);
  }
}

