async function authenticateRequest(request, env) {
  const header = request.headers.get('Authorization') || '';
  if (!header.startsWith('Bearer ')) return null;
  const token = header.slice(7).trim();
  const secret = await getTokenSecret(env);
  const userId = await verifyToken(token, secret);
  if (!userId) return null;
  const row = await env.DB.prepare('SELECT * FROM users WHERE id = ?').bind(userId).first();
  if (!row || !row.active) return null;
  return mapUserRow(row);
}

function hasPermission(user, perm) {
  return Boolean(user && (user.role === 'admin' || user.permissions?.[perm]));
}

async function parseBody(request) {
  try {
    return await request.json();
  } catch {
    return {};
  }
}

async function handleApiRequest(request, env, ctx) {
  await ensureSchema(env.DB);

  const url = new URL(request.url);
  const pathname = url.pathname;
  const method = request.method.toUpperCase();

  // --- Auth routes ---
  if (pathname === '/api/auth/status' && method === 'GET') {
    const countRow = await env.DB.prepare('SELECT COUNT(*) AS cnt FROM users').first();
    const setupRequired = Number(countRow?.cnt || 0) === 0;
    return json({
      setupRequired,
      envPasscodeActive: Boolean((env.ADMIN_PASSCODE || '').trim()),
    });
  }

  if (pathname === '/api/auth/setup-admin' && method === 'POST') {
    const countRow = await env.DB.prepare('SELECT COUNT(*) AS cnt FROM users').first();
    if (Number(countRow?.cnt || 0) > 0) {
      return json({ error: 'حساب مدیر کل قبلاً راه‌اندازی شده است.' }, 409);
    }
    const body = await parseBody(request);
    const { username, fullName, password } = body;
    if (typeof password !== 'string' || password.length < 6) {
      return json({ error: 'رمز عبور باید حداقل ۶ کاراکتر باشد.' }, 400);
    }
    const cleanUsername =
      typeof username === 'string' && username.trim().length >= 3 ? username.trim() : 'admin';
    const cleanName =
      typeof fullName === 'string' && fullName.trim() ? fullName.trim() : 'مدیر کل سیستم';
    const passwordHash = await hashPassword(password);
    const now = new Date().toISOString();
    const perms = defaultPermissionsForRole('admin');

    try {
      await env.DB.prepare(
        `INSERT INTO users (id, username, full_name, password_hash, role, active, permissions_json, created_at)
         VALUES (?, ?, ?, ?, 'admin', 1, ?, ?)`,
      )
        .bind('user-admin', cleanUsername, cleanName, passwordHash, JSON.stringify(perms), now)
        .run();
    } catch {
      return json({ error: 'حساب مدیر کل قبلاً راه‌اندازی شده است.' }, 409);
    }

    await seedInitialWarehouse(env.DB, cleanName);
    const row = await env.DB.prepare('SELECT * FROM users WHERE id = ?').bind('user-admin').first();
    const user = mapUserRow(row);
    const secret = await getTokenSecret(env);
    const token = await createToken(user, secret);
    return json({ token, user }, 201);
  }

  if (pathname === '/api/auth/login' && method === 'POST') {
    const body = await parseBody(request);
    const { username, password } = body;
    if (typeof username !== 'string' || typeof password !== 'string' || !username.trim() || !password) {
      return json({ error: 'نام کاربری و رمز عبور الزامی است.' }, 400);
    }
    const cleanUser = username.trim().toLowerCase();
    const row = await env.DB.prepare('SELECT * FROM users WHERE LOWER(username) = ?')
      .bind(cleanUser)
      .first();
    if (!row || !row.active) {
      return json({ error: 'نام کاربری یا رمز عبور اشتباه است یا حساب غیرفعال شده است.' }, 401);
    }

    const envPass = String(env.ADMIN_PASSCODE || '').trim();
    let valid = false;
    if (row.id === 'user-admin' && envPass && password === envPass) {
      valid = true;
    } else {
      valid = await verifyPassword(password, row.password_hash);
    }
    if (!valid) {
      return json({ error: 'نام کاربری یا رمز عبور اشتباه است یا حساب غیرفعال شده است.' }, 401);
    }
    const user = mapUserRow(row);
    const secret = await getTokenSecret(env);
    const token = await createToken(user, secret);
    return json({ token, user });
  }

  const currentUser = await authenticateRequest(request, env);
  if (!currentUser) {
    return json({ error: 'نشست کاربری معتبر نیست. لطفاً دوباره وارد شوید.' }, 401);
  }

  if (pathname === '/api/auth/me' && method === 'GET') {
    return json({ user: currentUser });
  }

  if (pathname === '/api/warehouse/bootstrap' && method === 'GET') {
    const canSeeUsers = hasPermission(currentUser, 'canManageUsers');
    const [items, movements, users, sheetConfig] = await Promise.all([
      listItems(env.DB),
      listMovements(env.DB),
      canSeeUsers ? listUsers(env.DB) : Promise.resolve([]),
      getSheetConfig(env.DB),
    ]);
    return json({ user: currentUser, items, movements, users, sheetConfig });
  }

  // --- Items ---
  if (pathname === '/api/items' && method === 'POST') {
    if (!hasPermission(currentUser, 'canManageItems')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const body = await parseBody(request);
    const { sku, name, category, unit, openingStock, minStock, warehouse, notes } = body;
    if (typeof sku !== 'string' || !sku.trim() || typeof name !== 'string' || !name.trim()) {
      return json({ error: 'کد کالا و نام کالا الزامی است.' }, 400);
    }
    const openNum = Number(openingStock ?? 0);
    const minNum = Number(minStock ?? 0);
    if (!Number.isFinite(openNum) || openNum < 0 || !Number.isFinite(minNum) || minNum < 0) {
      return json({ error: 'موجودی اول دوره و حداقل موجودی نباید منفی باشد.' }, 400);
    }
    const cleanSku = sku.trim();
    const existing = await env.DB.prepare('SELECT id FROM items WHERE LOWER(sku) = ?')
      .bind(cleanSku.toLowerCase())
      .first();
    if (existing) {
      return json({ error: 'این کد کالا قبلاً ثبت شده است.' }, 409);
    }
    const now = new Date().toISOString();
    const id = `item-${crypto.randomUUID().slice(0, 8)}`;
    const itemWh = normalizeWarehouseCode(typeof warehouse === 'string' ? warehouse : undefined);
    await env.DB.prepare(
      `INSERT INTO items (id, sku, name, category, unit, opening_stock, min_stock, warehouse, notes, created_at, created_by, updated_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    )
      .bind(
        id,
        cleanSku,
        name.trim(),
        typeof category === 'string' && category.trim() ? category.trim() : 'عمومی',
        typeof unit === 'string' && unit.trim() ? unit.trim() : 'عدد',
        openNum,
        minNum,
        itemWh,
        typeof notes === 'string' ? notes.trim() : '',
        now,
        currentUser.fullName,
        now,
      )
      .run();
    const saved = await env.DB.prepare('SELECT * FROM items WHERE id = ?').bind(id).first();
    scheduleSync(ctx, env);
    return json({ item: mapItemRow(saved) }, 201);
  }

  const itemMatch = pathname.match(/^\/api\/items\/([^/]+)$/);
  if (itemMatch && method === 'PUT') {
    if (!hasPermission(currentUser, 'canManageItems')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const id = decodeURIComponent(itemMatch[1]);
    const existingRow = await env.DB.prepare('SELECT * FROM items WHERE id = ?').bind(id).first();
    if (!existingRow) {
      return json({ error: 'کالای مورد نظر یافت نشد.' }, 404);
    }
    const body = await parseBody(request);
    const { sku, name, category, unit, openingStock, minStock, warehouse, notes } = body;
    const openNum = openingStock !== undefined ? Number(openingStock) : Number(existingRow.opening_stock);
    const minNum = minStock !== undefined ? Number(minStock) : Number(existingRow.min_stock);
    if (!Number.isFinite(openNum) || openNum < 0 || !Number.isFinite(minNum) || minNum < 0) {
      return json({ error: 'مقادیر عددی موجودی باید غیرمنفی باشند.' }, 400);
    }
    const nextSku = typeof sku === 'string' && sku.trim() ? sku.trim() : existingRow.sku;
    if (nextSku.toLowerCase() !== String(existingRow.sku).toLowerCase()) {
      const dup = await env.DB.prepare('SELECT id FROM items WHERE LOWER(sku) = ? AND id != ?')
        .bind(nextSku.toLowerCase(), id)
        .first();
      if (dup) return json({ error: 'کد کالا تکراری است.' }, 409);
    }
    const nextWh =
      typeof warehouse === 'string'
        ? normalizeWarehouseCode(warehouse)
        : normalizeWarehouseCode(existingRow.warehouse);
    const now = new Date().toISOString();
    await env.DB.prepare(
      `UPDATE items SET sku = ?, name = ?, category = ?, unit = ?, opening_stock = ?, min_stock = ?, warehouse = ?, notes = ?, updated_at = ? WHERE id = ?`,
    )
      .bind(
        nextSku,
        typeof name === 'string' && name.trim() ? name.trim() : existingRow.name,
        typeof category === 'string' ? category.trim() || 'عمومی' : existingRow.category,
        typeof unit === 'string' && unit.trim() ? unit.trim() : existingRow.unit,
        openNum,
        minNum,
        nextWh,
        typeof notes === 'string' ? notes.trim() : existingRow.notes,
        now,
        id,
      )
      .run();
    const updated = await env.DB.prepare('SELECT * FROM items WHERE id = ?').bind(id).first();
    scheduleSync(ctx, env);
    return json({ item: mapItemRow(updated) });
  }

  if (itemMatch && method === 'DELETE') {
    if (!hasPermission(currentUser, 'canDeleteData')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const id = decodeURIComponent(itemMatch[1]);
    const existingRow = await env.DB.prepare('SELECT id FROM items WHERE id = ?').bind(id).first();
    if (!existingRow) {
      return json({ error: 'کالای مورد نظر یافت نشد.' }, 404);
    }
    const movCountRow = await env.DB.prepare('SELECT COUNT(*) AS cnt FROM movements WHERE item_id = ?')
      .bind(id)
      .first();
    const removedMovementsCount = Number(movCountRow?.cnt || 0);
    await env.DB.batch([
      env.DB.prepare('DELETE FROM movements WHERE item_id = ?').bind(id),
      env.DB.prepare('DELETE FROM items WHERE id = ?').bind(id),
    ]);
    const [items, movements] = await Promise.all([listItems(env.DB), listMovements(env.DB)]);
    scheduleSync(ctx, env);
    return json({ deletedId: id, removedMovementsCount, items, movements });
  }

  if (pathname === '/api/warehouse/clear-data' && method === 'POST') {
    if (!hasPermission(currentUser, 'canDeleteData')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    await env.DB.batch([
      env.DB.prepare('DELETE FROM movements'),
      env.DB.prepare('DELETE FROM items'),
    ]);
    scheduleSync(ctx, env);
    return json({ items: [], movements: [] });
  }

  // --- Movements ---
  if (pathname === '/api/movements' && method === 'POST') {
    const body = await parseBody(request);
    const {
      type,
      warehouse,
      itemId,
      quantity,
      date,
      referenceNo,
      counterparty,
      notes,
      defectReason,
      custodianName,
      unitName,
      repairVendor,
      repairStatus,
      deductFromMain,
    } = body;
    if (type !== 'IN' && type !== 'OUT') {
      return json({ error: 'نوع تراکنش نامعتبر است.' }, 400);
    }
    if (type === 'IN' && !hasPermission(currentUser, 'canRecordIn')) {
      return json({ error: 'شما مجوز ثبت ورود کالا ندارید.' }, 403);
    }
    if (type === 'OUT' && !hasPermission(currentUser, 'canRecordOut')) {
      return json({ error: 'شما مجوز ثبت خروج کالا ندارید.' }, 403);
    }
    const targetWarehouse = normalizeWarehouseCode(
      typeof warehouse === 'string' ? warehouse : undefined,
    );
    const shouldDeductFromMain =
      Boolean(deductFromMain) && type === 'IN' && targetWarehouse !== 'MAIN';
    if (shouldDeductFromMain && !hasPermission(currentUser, 'canRecordOut')) {
      return json({ error: 'شما مجوز کسر از انبار اصلی را ندارید.' }, 403);
    }
    if (typeof itemId !== 'string' || !itemId.trim()) {
      return json({ error: 'انتخاب کالا الزامی است.' }, 400);
    }
    const qty = Number(quantity);
    if (!Number.isFinite(qty) || qty <= 0) {
      return json({ error: 'تعداد باید بزرگ‌تر از صفر باشد.' }, 400);
    }
    if (typeof date !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      return json({ error: 'فرمت تاریخ نامعتبر است.' }, 400);
    }
    const itemRow = await env.DB.prepare('SELECT * FROM items WHERE id = ?').bind(itemId).first();
    if (!itemRow) {
      return json({ error: 'کالای انتخاب‌شده یافت نشد.' }, 404);
    }
    const targetItem = mapItemRow(itemRow);
    const movements = type === 'OUT' || shouldDeductFromMain ? await listMovements(env.DB) : [];
    if (type === 'OUT') {
      const check = validateOutgoingQuantity(targetItem, movements, qty, undefined, targetWarehouse);
      if (!check.ok) {
        return json({ error: check.error }, 400);
      }
    }
    if (shouldDeductFromMain) {
      const mainCheck = validateOutgoingQuantity(targetItem, movements, qty, undefined, 'MAIN');
      if (!mainCheck.ok) {
        return json({ error: mainCheck.error }, 400);
      }
    }
    const id = `${type === 'IN' ? 'IN' : 'OUT'}-${crypto.randomUUID().slice(0, 6).toUpperCase()}`;
    const now = new Date().toISOString();
    const resolvedRepairStatus =
      repairStatus === 'SENT' || repairStatus === 'RETURNED'
        ? repairStatus
        : targetWarehouse === 'REPAIR' && type === 'IN'
          ? 'SENT'
          : '';
    await env.DB.prepare(
      `INSERT INTO movements (
        id, type, warehouse, item_id, quantity, date, reference_no, counterparty, notes,
        defect_reason, custodian_name, unit_name, repair_vendor, repair_status, returned_at,
        created_by_user_id, created_by_name, created_at, approval_status, sheet_sync_status
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, '', ?, ?, ?, 'PENDING', 'pending')`,
    )
      .bind(
        id,
        type,
        targetWarehouse,
        itemId,
        qty,
        date,
        typeof referenceNo === 'string' ? referenceNo.trim() : '',
        typeof counterparty === 'string' ? counterparty.trim() : '',
        typeof notes === 'string' ? notes.trim() : '',
        typeof defectReason === 'string' ? defectReason.trim() : '',
        typeof custodianName === 'string' ? custodianName.trim() : '',
        typeof unitName === 'string' ? unitName.trim() : '',
        typeof repairVendor === 'string' ? repairVendor.trim() : '',
        resolvedRepairStatus,
        currentUser.id,
        currentUser.fullName,
        now,
      )
      .run();

    let pairedMovement;
    if (shouldDeductFromMain) {
      const pairedId = `OUT-${crypto.randomUUID().slice(0, 6).toUpperCase()}`;
      const pairedCounterparty =
        (typeof custodianName === 'string' && custodianName.trim()) ||
        (typeof repairVendor === 'string' && repairVendor.trim()) ||
        WAREHOUSE_LABELS[targetWarehouse];
      await env.DB.prepare(
        `INSERT INTO movements (
          id, type, warehouse, item_id, quantity, date, reference_no, counterparty, notes,
          defect_reason, custodian_name, unit_name, repair_vendor, repair_status, returned_at,
          created_by_user_id, created_by_name, created_at, approval_status, sheet_sync_status
        ) VALUES (?, 'OUT', 'MAIN', ?, ?, ?, ?, ?, ?, '', '', '', '', '', '', ?, ?, ?, 'PENDING', 'pending')`,
      )
        .bind(
          pairedId,
          itemId,
          qty,
          date,
          typeof referenceNo === 'string' && referenceNo.trim() ? referenceNo.trim() : id,
          pairedCounterparty,
          `انتقال خودکار به ${WAREHOUSE_LABELS[targetWarehouse]} (${id})`,
          currentUser.id,
          currentUser.fullName,
          now,
        )
        .run();
      const pairedRow = await env.DB.prepare('SELECT * FROM movements WHERE id = ?')
        .bind(pairedId)
        .first();
      pairedMovement = mapMovementRow(pairedRow);
    }

    const saved = await env.DB.prepare('SELECT * FROM movements WHERE id = ?').bind(id).first();
    scheduleSync(ctx, env);
    return json({ movement: mapMovementRow(saved), pairedMovement }, 201);
  }

  const movReturnMatch = pathname.match(/^\/api\/movements\/([^/]+)\/return$/);
  if (movReturnMatch && method === 'POST') {
    const canAct =
      hasPermission(currentUser, 'canApprove') ||
      hasPermission(currentUser, 'canRecordIn') ||
      hasPermission(currentUser, 'canRecordOut');
    if (!canAct) {
      return json({ error: 'شما مجوز ثبت بازگشت ابزار یا کالا را ندارید.' }, 403);
    }
    const id = decodeURIComponent(movReturnMatch[1]);
    const row = await env.DB.prepare('SELECT * FROM movements WHERE id = ?').bind(id).first();
    if (!row) {
      return json({ error: 'سند مورد نظر یافت نشد.' }, 404);
    }
    const wh = normalizeWarehouseCode(row.warehouse);
    if ((wh !== 'REPAIR' && wh !== 'CUSTODY') || row.type !== 'IN') {
      return json({ error: 'امکان ثبت بازگشت فقط برای اقلام امانی یا تعمیراتی وجود دارد.' }, 400);
    }
    if (row.approval_status !== 'APPROVED') {
      return json({ error: 'این سند هنوز به تایید مدیریت نرسیده است.' }, 400);
    }
    if (row.repair_status === 'RETURNED') {
      return json({ error: 'بازگشت این مورد قبلاً ثبت شده است.' }, 409);
    }

    const body = await parseBody(request);
    const { returnToMain, date, note } = body;
    const returnDate =
      typeof date === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(date) ? date : ymdDaysAgo(0);
    const cleanNote = typeof note === 'string' ? note.trim() : '';
    const autoApprove = hasPermission(currentUser, 'canApprove');
    const approvalStatus = autoApprove ? 'APPROVED' : 'PENDING';
    const now = new Date().toISOString();

    await env.DB.prepare(
      `UPDATE movements SET repair_status = 'RETURNED', returned_at = ?, sheet_sync_status = 'pending' WHERE id = ?`,
    )
      .bind(returnDate, id)
      .run();

    const retId = `OUT-${crypto.randomUUID().slice(0, 6).toUpperCase()}`;
    const party = row.repair_vendor || row.custodian_name || row.counterparty || 'انبار';
    const retNotes =
      cleanNote || `${wh === 'REPAIR' ? 'بازگشت از تعمیر' : 'عودت از امانی'} (سند ${id})`;
    await env.DB.prepare(
      `INSERT INTO movements (
        id, type, warehouse, item_id, quantity, date, reference_no, counterparty, notes,
        defect_reason, custodian_name, unit_name, repair_vendor, repair_status, returned_at,
        created_by_user_id, created_by_name, created_at, approval_status,
        approved_by_user_id, approved_by_name, approved_at, approval_note, sheet_sync_status
      ) VALUES (?, 'OUT', ?, ?, ?, ?, ?, ?, ?, '', '', '', '', '', '', ?, ?, ?, ?, ?, ?, ?, ?, 'pending')`,
    )
      .bind(
        retId,
        wh,
        row.item_id,
        Number(row.quantity),
        returnDate,
        row.reference_no || id,
        party,
        retNotes,
        currentUser.id,
        currentUser.fullName,
        now,
        approvalStatus,
        autoApprove ? currentUser.id : null,
        autoApprove ? currentUser.fullName : null,
        autoApprove ? now : null,
        autoApprove ? 'ثبت و تایید خودکار بازگشت' : null,
      )
      .run();

    let mainReturnMovement;
    if (returnToMain) {
      const mainId = `IN-${crypto.randomUUID().slice(0, 6).toUpperCase()}`;
      const mainNotes =
        cleanNote || `ورود مجدد به انبار اصلی از ${WAREHOUSE_LABELS[wh]} (سند ${id})`;
      await env.DB.prepare(
        `INSERT INTO movements (
          id, type, warehouse, item_id, quantity, date, reference_no, counterparty, notes,
          defect_reason, custodian_name, unit_name, repair_vendor, repair_status, returned_at,
          created_by_user_id, created_by_name, created_at, approval_status,
          approved_by_user_id, approved_by_name, approved_at, approval_note, sheet_sync_status
        ) VALUES (?, 'IN', 'MAIN', ?, ?, ?, ?, ?, ?, '', '', '', '', '', '', ?, ?, ?, ?, ?, ?, ?, ?, 'pending')`,
      )
        .bind(
          mainId,
          row.item_id,
          Number(row.quantity),
          returnDate,
          row.reference_no || id,
          party,
          mainNotes,
          currentUser.id,
          currentUser.fullName,
          now,
          approvalStatus,
          autoApprove ? currentUser.id : null,
          autoApprove ? currentUser.fullName : null,
          autoApprove ? now : null,
          autoApprove ? 'ثبت و تایید خودکار بازگشت' : null,
        )
        .run();
      const mainRow = await env.DB.prepare('SELECT * FROM movements WHERE id = ?')
        .bind(mainId)
        .first();
      mainReturnMovement = mapMovementRow(mainRow);
    }

    const [origRow, retRow] = await Promise.all([
      env.DB.prepare('SELECT * FROM movements WHERE id = ?').bind(id).first(),
      env.DB.prepare('SELECT * FROM movements WHERE id = ?').bind(retId).first(),
    ]);
    scheduleSync(ctx, env);
    return json({
      updatedOriginal: mapMovementRow(origRow),
      returnMovement: mapMovementRow(retRow),
      mainReturnMovement,
    });
  }

  const movActionMatch = pathname.match(/^\/api\/movements\/([^/]+)\/(approve|reject)$/);
  if (movActionMatch && method === 'POST') {
    if (!hasPermission(currentUser, 'canApprove')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const id = decodeURIComponent(movActionMatch[1]);
    const decision = movActionMatch[2] === 'approve' ? 'APPROVED' : 'REJECTED';
    const row = await env.DB.prepare('SELECT * FROM movements WHERE id = ?').bind(id).first();
    if (!row) {
      return json({ error: 'سند مورد نظر یافت نشد.' }, 404);
    }
    if (row.approval_status !== 'PENDING') {
      return json({ error: 'این سند قبلاً بررسی شده است.' }, 409);
    }
    if (decision === 'APPROVED' && row.type === 'OUT') {
      const itemRow = await env.DB.prepare('SELECT * FROM items WHERE id = ?')
        .bind(row.item_id)
        .first();
      if (itemRow) {
        const movements = await listMovements(env.DB);
        const check = validateOutgoingQuantity(
          mapItemRow(itemRow),
          movements,
          Number(row.quantity),
          id,
          normalizeWarehouseCode(row.warehouse),
        );
        if (!check.ok) {
          return json({ error: check.error }, 400);
        }
      }
    }
    const body = await parseBody(request);
    const approvalNote = typeof body.approvalNote === 'string' ? body.approvalNote.trim() : '';
    const now = new Date().toISOString();
    await env.DB.prepare(
      `UPDATE movements SET approval_status = ?, approved_by_user_id = ?, approved_by_name = ?, approved_at = ?, approval_note = ?, sheet_sync_status = 'pending' WHERE id = ?`,
    )
      .bind(decision, currentUser.id, currentUser.fullName, now, approvalNote, id)
      .run();
    const updated = await env.DB.prepare('SELECT * FROM movements WHERE id = ?').bind(id).first();
    scheduleSync(ctx, env);
    return json({ movement: mapMovementRow(updated) });
  }

  const movDeleteMatch = pathname.match(/^\/api\/movements\/([^/]+)$/);
  if (movDeleteMatch && method === 'DELETE') {
    if (!hasPermission(currentUser, 'canDeleteData')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const id = decodeURIComponent(movDeleteMatch[1]);
    const row = await env.DB.prepare('SELECT id FROM movements WHERE id = ?').bind(id).first();
    if (!row) {
      return json({ error: 'سند مورد نظر یافت نشد.' }, 404);
    }
    await env.DB.prepare('DELETE FROM movements WHERE id = ?').bind(id).run();
    scheduleSync(ctx, env);
    return json({ deletedId: id });
  }

  // --- Users ---
  if (pathname === '/api/users' && method === 'GET') {
    if (!hasPermission(currentUser, 'canManageUsers')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    return json({ users: await listUsers(env.DB) });
  }

  if (pathname === '/api/users' && method === 'POST') {
    if (!hasPermission(currentUser, 'canManageUsers')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const body = await parseBody(request);
    const { username, fullName, password, role, permissions } = body;
    if (
      typeof username !== 'string' ||
      username.trim().length < 3 ||
      typeof fullName !== 'string' ||
      !fullName.trim() ||
      typeof password !== 'string' ||
      password.length < 4
    ) {
      return json(
        { error: 'نام کاربری (حداقل ۳ حرف)، نام کامل و رمز عبور (حداقل ۴ کاراکتر) الزامی است.' },
        400,
      );
    }
    const cleanUsername = username.trim();
    const existing = await env.DB.prepare('SELECT id FROM users WHERE LOWER(username) = ?')
      .bind(cleanUsername.toLowerCase())
      .first();
    if (existing) {
      return json({ error: 'این نام کاربری قبلاً تعریف شده است.' }, 409);
    }
    const safeRole = role === 'admin' || role === 'manager' || role === 'operator' ? role : 'operator';
    const mergedPerms = mergePermissions(safeRole, permissions);
    const id = `user-${crypto.randomUUID().slice(0, 8)}`;
    const now = new Date().toISOString();
    const passwordHash = await hashPassword(password);
    await env.DB.prepare(
      `INSERT INTO users (id, username, full_name, password_hash, role, active, permissions_json, created_at)
       VALUES (?, ?, ?, ?, ?, 1, ?, ?)`,
    )
      .bind(
        id,
        cleanUsername,
        fullName.trim(),
        passwordHash,
        safeRole,
        JSON.stringify(mergedPerms),
        now,
      )
      .run();
    const saved = await env.DB.prepare('SELECT * FROM users WHERE id = ?').bind(id).first();
    return json({ user: mapUserRow(saved) }, 201);
  }

  const userMatch = pathname.match(/^\/api\/users\/([^/]+)$/);
  if (userMatch && method === 'PUT') {
    if (!hasPermission(currentUser, 'canManageUsers')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const id = decodeURIComponent(userMatch[1]);
    const row = await env.DB.prepare('SELECT * FROM users WHERE id = ?').bind(id).first();
    if (!row) {
      return json({ error: 'کاربر یافت نشد.' }, 404);
    }
    const body = await parseBody(request);
    const { fullName, role, active, permissions, password } = body;
    if (id === 'user-admin' && active === false) {
      return json({ error: 'امکان غیرفعال کردن مدیر کل اصلی وجود ندارد.' }, 400);
    }
    if (typeof password === 'string' && password.length > 0 && password.length < 4) {
      return json({ error: 'رمز عبور جدید باید حداقل ۴ کاراکتر باشد.' }, 400);
    }
    const nextRole =
      id === 'user-admin'
        ? 'admin'
        : role === 'admin' || role === 'manager' || role === 'operator'
          ? role
          : row.role;
    let currentPerms = defaultPermissionsForRole(row.role);
    try {
      currentPerms = JSON.parse(row.permissions_json);
    } catch {
      // ignore
    }
    const nextPerms =
      id === 'user-admin'
        ? defaultPermissionsForRole('admin')
        : permissions && typeof permissions === 'object'
          ? mergePermissions(nextRole, permissions)
          : mergePermissions(nextRole, currentPerms);
    const nextPasswordHash =
      typeof password === 'string' && password.trim()
        ? await hashPassword(password)
        : row.password_hash;

    await env.DB.prepare(
      `UPDATE users SET full_name = ?, role = ?, active = ?, permissions_json = ?, password_hash = ? WHERE id = ?`,
    )
      .bind(
        typeof fullName === 'string' && fullName.trim() ? fullName.trim() : row.full_name,
        nextRole,
        typeof active === 'boolean' ? (active ? 1 : 0) : row.active,
        JSON.stringify(nextPerms),
        nextPasswordHash,
        id,
      )
      .run();
    const updated = await env.DB.prepare('SELECT * FROM users WHERE id = ?').bind(id).first();
    return json({ user: mapUserRow(updated) });
  }

  // --- Google Sheets ---
  if (pathname === '/api/sheets/config' && method === 'PUT') {
    if (!hasPermission(currentUser, 'canSyncSheets')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const body = await parseBody(request);
    const { spreadsheetInput, spreadsheetTitle, webhookUrl, autoSyncOnChange } = body;
    const cleanId =
      typeof spreadsheetInput === 'string' ? extractSpreadsheetId(spreadsheetInput) : '';
    const cleanWebhook = typeof webhookUrl === 'string' ? webhookUrl.trim() : '';
    if (cleanWebhook && !isValidAppsScriptUrl(cleanWebhook)) {
      return json(
        { error: 'آدرس وب‌هوک نامعتبر است. باید با https://script.google.com/macros/ شروع شود.' },
        400,
      );
    }
    const cleanUrl = cleanId ? `https://docs.google.com/spreadsheets/d/${cleanId}/edit` : '';
    const cleanTitle =
      typeof spreadsheetTitle === 'string' && spreadsheetTitle.trim()
        ? spreadsheetTitle.trim()
        : 'سامانه انبارداری - گزارش آنلاین';
    const autoFlag = typeof autoSyncOnChange === 'boolean' ? (autoSyncOnChange ? 1 : 0) : 1;

    await env.DB.prepare(
      `UPDATE sheet_config SET spreadsheet_id = ?, spreadsheet_url = ?, spreadsheet_title = ?, webhook_url = ?, auto_sync_on_change = ? WHERE id = 1`,
    )
      .bind(cleanId, cleanUrl, cleanTitle, cleanWebhook, autoFlag)
      .run();

    return json({ sheetConfig: await getSheetConfig(env.DB) });
  }

  if (pathname === '/api/sheets/create' && method === 'POST') {
    if (!hasPermission(currentUser, 'canSyncSheets')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const googleToken = request.headers.get('X-Google-Token') || '';
    if (!googleToken) {
      return json({ error: 'ابتدا باید با حساب گوگل وارد شوید.' }, 401);
    }
    const body = await parseBody(request);
    const title =
      typeof body.title === 'string' ? body.title : 'سامانه انبارداری - گزارش آنلاین';
    try {
      const created = await createWarehouseSpreadsheet(googleToken, title);
      const [items, movements] = await Promise.all([listItems(env.DB), listMovements(env.DB)]);
      const tabs = buildGoogleSheetPayloads(items, movements);
      await syncToGoogleSheetsViaOAuth(googleToken, created.spreadsheetId, tabs);
      await env.DB.prepare(
        `UPDATE sheet_config SET spreadsheet_id = ?, spreadsheet_url = ?, spreadsheet_title = ? WHERE id = 1`,
      )
        .bind(created.spreadsheetId, created.spreadsheetUrl, created.title)
        .run();
      await markAllMovementsSync(env.DB, 'synced', 'گوگل شیت با ۴ برگه ایجاد و همگام‌سازی شد');
      return json(
        {
          sheetConfig: await getSheetConfig(env.DB),
          movements: await listMovements(env.DB),
          created,
        },
        201,
      );
    } catch (err) {
      return json({ error: err instanceof Error ? err.message : 'خطا در ایجاد گوگل شیت' }, 502);
    }
  }

  if (pathname === '/api/sheets/sync' && method === 'POST') {
    if (!hasPermission(currentUser, 'canSyncSheets')) {
      return json({ error: 'شما مجوز انجام این عملیات را ندارید.' }, 403);
    }
    const body = await parseBody(request);
    const mode = body.mode === 'webhook' ? 'webhook' : 'oauth';
    const [items, movements, cfg] = await Promise.all([
      listItems(env.DB),
      listMovements(env.DB),
      getSheetConfig(env.DB),
    ]);
    const tabs = buildGoogleSheetPayloads(items, movements);

    try {
      if (mode === 'webhook') {
        if (!cfg.webhookUrl) {
          return json({ error: 'آدرس وب‌هوک Apps Script تنظیم نشده است.' }, 400);
        }
        const result = await syncToAppsScriptWebhook(cfg.webhookUrl, tabs, {
          spreadsheetId: cfg.spreadsheetId,
          spreadsheetTitle: cfg.spreadsheetTitle,
        });
        if (!cfg.spreadsheetId && result.spreadsheetId) {
          const sheetUrl =
            result.spreadsheetUrl ||
            `https://docs.google.com/spreadsheets/d/${result.spreadsheetId}/edit`;
          await env.DB.prepare(
            'UPDATE sheet_config SET spreadsheet_id = ?, spreadsheet_url = ? WHERE id = 1',
          )
            .bind(result.spreadsheetId, sheetUrl)
            .run();
        }
        await markAllMovementsSync(env.DB, 'synced', 'همگام‌سازی ۴ برگه از طریق وب‌هوک انجام شد');
        return json({
          sheetConfig: await getSheetConfig(env.DB),
          movements: await listMovements(env.DB),
        });
      }

      const googleToken = request.headers.get('X-Google-Token') || '';
      if (!googleToken) {
        return json({ error: 'توکن گوگل یافت نشد. لطفاً با حساب گوگل وارد شوید.' }, 401);
      }
      if (!cfg.spreadsheetId) {
        return json(
          { error: 'ابتدا یک گوگل شیت جدید بسازید یا شناسه گوگل شیت را ثبت کنید.' },
          400,
        );
      }
      await syncToGoogleSheetsViaOAuth(googleToken, cfg.spreadsheetId, tabs);
      await markAllMovementsSync(env.DB, 'synced', 'همگام‌سازی ۴ برگه با گوگل شیت انجام شد');
      return json({
        sheetConfig: await getSheetConfig(env.DB),
        movements: await listMovements(env.DB),
      });
    } catch (err) {
      const msg = err instanceof Error ? err.message : 'خطا در همگام‌سازی با گوگل شیت';
      await markAllMovementsSync(env.DB, 'error', msg);
      return json(
        {
          error: msg,
          sheetConfig: await getSheetConfig(env.DB),
          movements: await listMovements(env.DB),
        },
        502,
      );
    }
  }

  return json({ error: 'مسیر درخواستی یافت نشد.' }, 404);
}

async function proxyUpstream(request, env) {
  const upstreamOrigin = (env && env.UPSTREAM_ORIGIN) || DEFAULT_UPSTREAM_ORIGIN;
  const incomingUrl = new URL(request.url);
  const upstreamUrl = new URL(incomingUrl.pathname + incomingUrl.search, upstreamOrigin);

  const headers = new Headers(request.headers);
  headers.set('Host', new URL(upstreamOrigin).host);
  headers.set('X-Forwarded-Host', incomingUrl.host);
  headers.set('X-Forwarded-Proto', incomingUrl.protocol.replace(':', ''));
  headers.delete('cf-connecting-ip');
  headers.delete('cf-ipcountry');
  headers.delete('cf-ray');
  headers.delete('cf-visitor');

  const init = {
    method: request.method,
    headers,
    redirect: 'manual',
  };
  if (request.method !== 'GET' && request.method !== 'HEAD') {
    init.body = request.body;
  }

  const upstreamResponse = await fetch(upstreamUrl.toString(), init);
  const responseHeaders = new Headers(upstreamResponse.headers);
  const location = responseHeaders.get('Location');
  if (location && location.startsWith(upstreamOrigin)) {
    responseHeaders.set('Location', location.replace(upstreamOrigin, incomingUrl.origin));
  }

  return new Response(upstreamResponse.body, {
    status: upstreamResponse.status,
    statusText: upstreamResponse.statusText,
    headers: responseHeaders,
  });
}

async function serveEmbeddedAsset(pathname) {
  if (!EMBEDDED_ASSETS) return null;
  const cleanPath = pathname === '/' ? '/index.html' : pathname;
  let entry = EMBEDDED_ASSETS[cleanPath];
  let isAsset = Boolean(entry) && cleanPath.startsWith('/assets/');
  if (!entry) {
    if (/\.[a-z0-9]{1,8}$/i.test(cleanPath)) {
      return new Response('Not Found', { status: 404 });
    }
    entry = EMBEDDED_ASSETS['/index.html'];
    isAsset = false;
  }
  if (!entry) return null;
  const gzBytes = base64Decode(entry.gz);
  const stream = new Response(gzBytes).body.pipeThrough(new DecompressionStream('gzip'));
  return new Response(stream, {
    status: 200,
    headers: {
      'Content-Type': entry.type,
      'Cache-Control': isAsset ? 'public, max-age=31536000, immutable' : 'no-cache',
    },
  });
}

export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);

    // If D1 database binding (DB) is attached, handle all /api/* permanently on Cloudflare D1
    if (url.pathname.startsWith('/api/')) {
      if (env && env.DB) {
        try {
          return await handleApiRequest(request, env, ctx);
        } catch (err) {
          console.error('Worker API error:', err);
          return json({ error: 'خطای داخلی سرور کلودفلر.' }, 500);
        }
      }
      if ((env && env.ASSETS) || EMBEDDED_ASSETS) {
        return json(
          { error: 'دیتابیس D1 هنوز به Worker متصل نشده است (Binding با نام DB).' },
          503,
        );
      }
      return proxyUpstream(request, env);
    }

    // Serve static frontend embedded inside standalone Worker bundle
    if (EMBEDDED_ASSETS) {
      const embeddedRes = await serveEmbeddedAsset(url.pathname);
      if (embeddedRes) return embeddedRes;
    }

    // Serve static frontend from Cloudflare Assets if deployed via Wrangler / GitHub
    if (env && env.ASSETS && typeof env.ASSETS.fetch === 'function') {
      const assetRes = await env.ASSETS.fetch(request);
      if (assetRes.status !== 404) {
        return assetRes;
      }
      return env.ASSETS.fetch(new Request(new URL('/index.html', request.url), request));
    }

    // Otherwise fall back to proxying static files
    return proxyUpstream(request, env);
  },
};
